// ---------- OWNER: dashboard, properties, rooms & beds, residents, reservations ----------
const M1='M1 Dashboard',M2='M2 Properties',M3='M3 Buildings, rooms & beds',M4='M4 Residents & KYC',M5='M5 Reservations';
const fdate=s=>{if(!s)return '';const d=new Date(s+'T00:00');return isNaN(d)?s:`${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`};
const dnum=s=>{const d=new Date(s+'T00:00');return Math.round((d-new Date(2026,11,1))/864e5)+1};

def('oHome',{t:'Owner dashboard',m:M1,r:'owner',tab:'oHome',code:'D-01',
 d:'The owner’s daily overview. The chip under the greeting is the property switcher: “All Properties” shows the whole business combined, picking one property filters every number, list and action on this screen and across the app.',
 try:['Tap the “All Properties” chip and pick Sunrise Boys PG — the whole dashboard changes.','Tap a property row under “Properties” to jump into it directly.','Tap “7 rents overdue” to land on the filtered invoice list.'],
 empty:{icon:'users',title:'Add your first resident',msg:'45 beds are ready in Sunrise Boys PG. Add residents to start collecting rent.',cta:'Add resident',go:'resAdd'},
 v:()=>{const s=stats(),all=ST.prop==='all',P=all?null:PR(ST.prop),tot=sum(DB.inv,i=>i.total),f=tot?s.billed/tot:1;
 const hist=[['Jul',9.1,2.9],['Aug',9.4,3.0],['Sep',9.8,3.3],['Oct',10.2,3.1],['Nov',10.6,3.2]].map(([l,a,b])=>({l,v:a*f*100000*(tot/1100000),v2:b*f*100000*(tot/1100000)}));hist.push({l:'Dec',v:s.paid,v2:s.exp});
 const up=DB.resv.filter(r=>inS(r.propId)&&['Confirmed','Pending payment'].includes(r.status)).slice(0,2),outs=sRes().filter(r=>r.status==='Notice').slice(0,2);
 return page({bar:`<div class="ab"><div style="flex:1;min-width:0"><div class="t-s mut">Namaste, Deven</div><div style="margin-top:4px">${propChip()}</div></div><button class="ib" data-go="activity" aria-label="Activity">${ic('clock')}</button><button class="ib" data-go="oNotifs" aria-label="Notifications">${ic('bell')}${DB.notifs.some(n=>!n.read)?'<span class="dot"></span>':''}</button></div>`,body:`
 ${P?illus(P,104,`<span class="bdg" style="background:#fff;color:var(--ink)">${ic('pin','sm')}${P.area}, ${P.city}</span>${sb(P.status)}`):''}
 ${card(`<div class="row" style="gap:14px">${ring(pct(s.occ,s.beds),'occupancy')}<div style="flex:1" class="stack"><div class="between">${lbl(`Occupancy · ${s.beds} beds`)}<span class="lnk" data-go="occMap">Bed map</span></div><div class="t-s" style="display:grid;grid-template-columns:1fr 1fr;gap:3px 10px"><span><b>${s.occ}</b> <span class="mut">occupied</span></span><span><b>${s.av}</b> <span class="mut">available</span></span><span><b>${s.res}</b> <span class="mut">reserved</span></span><span><b>${s.mn+s.ina}</b> <span class="mut">maint./inactive</span></span></div>${bedStack(s)}</div></div>`)}
 ${card(`<div class="between">${lbl('December rent collection')}${bdg(pct(s.paid,s.billed)+'% collected',pct(s.paid,s.billed)>85?'ok':'warn')}</div><div class="between" style="margin:4px 0 6px"><span class="t-xl w7 num">${inr(s.paid)}</span><span class="t-s mut num">of ${inr(s.billed)}</span></div>${bar([[pct(s.paid,s.billed),'var(--green)']])}`,'',{go:'finHome'})}
 <div class="g2">${stat('Pending rent',inr(s.pending),`${s.dueCount} residents`,'var(--red)')}${stat('Overdue',inr(s.overdue),`${s.odCount} past due date`,'var(--amber)')}${stat('Expenses',inr(s.exp),'Last 30 days')}${stat('Net cash',inr(s.paid-s.exp),'Collected − expenses')}</div>
 ${sec('Quick actions')}
 <div class="qa">${[['users','Add resident','resAdd','var(--blue-50)','var(--blue)'],['rupee','Collect rent','payRecord','var(--green-50)','var(--green)'],['cal','Reservation','resvCreate','var(--violet-50)','var(--violet)'],['receipt','Add expense','expAdd','var(--amber-50)','var(--amber)'],['wrench','Complaints','compList','var(--red-50)','var(--red)'],all?['bldg','Add property','propForm','var(--slate-50)','var(--ink-2)']:['door','Visitor entry','visitorAdd','var(--slate-50)','var(--ink-2)']].map(([i,l,g,bg,fg])=>`<div data-go="${g}" role="button" tabindex="0"><span class="tile" style="background:${bg};color:${fg}">${ic(i)}</span>${l}</div>`).join('')}</div>
 ${sec('Needs attention')}
 ${list([s.odCount?li({icon:'rupee',bg:'var(--red-50)',fg:'var(--red)',title:`${s.odCount} rents overdue`,sub:`${inr(s.overdue)} incl. late fees`,right:btn('Remind',{k:'wa',sm:true,act:'sheet',p:{s:'remind'}}),chev:false}):'',
  s.verify?li({icon:'shield',bg:'var(--amber-50)',fg:'var(--amber)',title:`${s.verify} UPI payments to verify`,sub:'Residents paid directly and shared UTR',go:'upiVerify'}):'',
  li({icon:'wrench',bg:'var(--amber-50)',fg:'var(--amber)',title:`${s.open} open complaints`,sub:`${s.unasg} not assigned yet`,go:'compList'}),
  li({icon:'badge',bg:'var(--blue-50)',fg:'var(--blue)',title:`${s.kyc} KYC pending`,sub:`${s.police} police verifications pending`,go:'resList',p:{f:'kyc'}})].filter(Boolean))}
 ${all?sec('Properties','See all',{tab:'propList'})+list(DB.props.map(P=>{const b=DB.beds.filter(x=>x.propId===P.id),o=b.filter(x=>x.status==='Occupied').length,pi=DB.inv.filter(i=>i.propId===P.id),pend=sum(pi,i=>i.total-i.paid);return li({lead:propTile(P),title:P.name,sub:`${P.city} · ${o}/${b.length} beds`,sub2:`<div style="margin-top:5px">${bar([[pct(o,b.length),pct(o,b.length)<75?'var(--amber)':'var(--blue)']])}</div>`,right:`<b>${pct(o,b.length)}%</b><span class="t-xs c-err">${inr(pend)} due</span>`,act:'setProp',p:{id:P.id}})}))
 :''}
 ${card(`<div class="between"><b>Collections vs expenses</b><span class="t-s mut">6 months</span></div>${bars(hist,{two:true,n1:'Rent collected',n2:'Expenses',fmt:v=>v>=100000?(v/100000).toFixed(1)+'L':Math.round(v/1000)+'k',label:'Collections vs expenses'})}`,'stack')}
 ${sec('Upcoming check-ins & check-outs')}
 ${list([...up.map(r=>li({lead:bdg('IN','ok'),title:r.name,sub:`${PR(r.propId).short} · ${bedName(BD(r.bedId))} · ${r.from}`,go:'resvDetail',p:{id:r.id}})),...outs.map(r=>li({lead:bdg('OUT','warn'),title:r.name,sub:`${loc(r)} · ${r.checkout}`,go:'resProfile',p:{id:r.id}}))].concat(up.length+outs.length?[]:[li({title:'Nothing scheduled this week',sub:'New reservations will show here'})]))}
 ${sec('Recent activity','View all',{go:'activity'})}
 ${list(activityItems().slice(0,3))}`})}});

function activityItems(){
  const it=[];DB.pay.filter(p=>inS(p.propId)).slice(-4).reverse().forEach(p=>it.push(li({icon:'rupee',bg:'var(--green-50)',fg:'var(--green)',title:`${RS(p.resId).name} paid ${inr(p.amt)}`,sub:`${p.method}${p.status==='Verifying'?' · awaiting verification':''} · ${PR(p.propId).short} · ${p.date}`,go:'payDetail',p:{id:p.id}})));
  sComp().slice(0,2).forEach(c=>it.push(li({icon:'wrench',bg:'var(--amber-50)',fg:'var(--amber)',title:`Complaint: ${c.title}`,sub:`${PR(c.propId).short} · ${c.room} · ${c.created}`,go:'compDetail',p:{id:c.id}})));
  DB.resv.filter(r=>inS(r.propId)).slice(0,1).forEach(r=>it.push(li({icon:'cal',bg:'var(--violet-50)',fg:'var(--violet)',title:`Bed reserved for ${r.name}`,sub:`${bedName(BD(r.bedId))} · advance ${inr(r.advance)}`,go:'resvDetail',p:{id:r.id}})));
  sExp().slice(0,1).forEach(e=>it.push(li({icon:'receipt',title:`Expense ${inr(e.amt)} · ${e.vendor}`,sub:`${PR(e.propId).short} · by ${e.by}`,go:'expDetail',p:{id:e.id}})));
  const k=sRes().find(r=>r.kyc==='Submitted');if(k)it.splice(2,0,li({icon:'badge',bg:'var(--blue-50)',fg:'var(--blue)',title:`${k.name} uploaded KYC`,sub:`${loc(k)} · waiting for review`,go:'kycVerify',p:{id:k.id}}));
  return it;
}
def('activity',{t:'Recent activity',m:M1,r:'owner',tab:'oHome',code:'D-05',d:'Everything that happened in the selected property scope, newest first. Every row opens its record. Built from the audit log.',try:['Use the filter chips.','Tap a payment row to open it.'],
 v:()=>{const f=U(K('acF'),'all');let it=activityItems();if(f!=='all')it=it.filter(x=>x.includes({pay:'i-rupee',comp:'i-wrench',res:'i-badge'}[f]));
 return page({chip:true,body:`${chips(K('acF'),[['all','All'],['pay','Payments'],['comp','Complaints'],['res','Residents']],'all')}${lbl('Today & yesterday')}${list(it)}`})}});

def('oNotifs',{t:'Notifications',m:'M12 Notifications',r:'owner',tab:'oHome',code:'N-01',d:'Owner notification inbox: payments, complaints, KYC, reservations, check-outs, document expiry and subscription reminders. Tapping one opens the related screen and marks it read.',try:['Tap “Payment received” or the complaint notification.','Tap the gear for notification preferences.'],
 empty:{icon:'bell',title:'You’re all caught up',msg:'New payments, complaints and reminders will appear here.'},
 v:()=>{const f=U('nF','all'),n=DB.notifs.filter(x=>f==='all'||!x.read);const icn={pay:['rupee','var(--green-50)','var(--green)'],comp:['wrench','var(--amber-50)','var(--amber)'],upi:['shield','var(--amber-50)','var(--amber)'],kyc:['badge','var(--blue-50)','var(--blue)'],resv:['cal','var(--violet-50)','var(--violet)'],out:['out','var(--slate-50)','var(--ink-2)'],doc:['file','var(--red-50)','var(--red)'],sub:['star','var(--blue-50)','var(--blue)']};
 return page({right:`<button class="ib" data-go="notifSettings" aria-label="Settings">${ic('gear')}</button>`,body:`<div class="between">${chips('nF',[['all','All'],['unread','Unread',DB.notifs.filter(x=>!x.read).length]],'all')}<span class="lnk" data-act="readAll">Mark all read</span></div>
 ${n.length?list(n.map(x=>{const [i,bg,fg]=icn[x.type];return li({icon:i,bg,fg,title:`${x.read?'':'<span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--blue);margin-right:6px;vertical-align:middle"></span>'}${x.title}`,sub:x.text,sub2:x.time,act:'openNotif',p:{id:x.id}})})):emptyB({icon:'bell',title:'No unread notifications',msg:'You’ve read everything.'})}`})}});
A.readAll=()=>{DB.notifs.forEach(n=>n.read=true);render();toast('All notifications marked as read')};
A.openNotif=p=>{const n=DB.notifs.find(x=>x.id===p.id);n.read=true;go(n.go,n.p||{})};

def('oMore',{t:'More',m:'Navigation',r:'owner',tab:'oMore',code:'D-04',d:'Holds everything that doesn’t need a bottom-tab of its own: complaints, reservations, staff, visitors, food & mess, notices, reports, subscription and settings. Keeps the bottom bar to five items.',
 v:()=>{const s=stats();const g=(i,l,go,bg,fg,n)=>`<div data-go="${go}" role="button" tabindex="0" style="position:relative"><span class="tile" style="background:${bg};color:${fg}">${ic(i)}</span>${l}${n?`<span class="bdg b-err" style="position:absolute;top:6px;right:8px">${n}</span>`:''}</div>`;
 return page({chip:true,body:`${card(`<div class="row"><div class="av" style="width:46px;height:46px;background:var(--navy);color:#fff">DP</div><div style="flex:1"><div class="w7">Deven Patel</div><div class="t-s mut">Deven PG Group · Owner</div></div>${bdg('Professional','info')}</div>`,'',{go:'ownerProfile'})}
 ${lbl('Operations')}<div class="qa">${g('wrench','Complaints','compList','var(--red-50)','var(--red)',s.open)}${g('cal','Reservations','resvList','var(--violet-50)','var(--violet)')}${g('badge','Staff','staffList','var(--blue-50)','var(--blue)')}${g('door','Visitors','visitors','var(--slate-50)','var(--ink-2)')}${g('food','Food & mess','mess','var(--amber-50)','var(--amber)')}${g('mega','Notices','annList','var(--green-50)','var(--green)')}</div>
 ${lbl('Business')}${list([li({icon:'chart',title:'Reports & analytics',sub:'Revenue, occupancy, P&L, exports',go:'reports'}),li({icon:'star',title:'Subscription',sub:`Professional · renews ${SUB.renews}`,go:'sub'}),li({icon:'bell',title:'Notifications',go:'oNotifs'}),li({icon:'gear',title:'Settings',go:'settings'}),li({icon:'help',title:'Help & support',go:'help'})])}
 ${list([li({icon:'logout',fg:'var(--red)',bg:'var(--red-50)',title:'<span class="c-err">Log out</span>',act:'askLogout'})])}`})}});
A.askLogout=()=>confirmD({icon:'logout',danger:true,title:'Log out of PG ERP?',msg:'You’ll need an OTP to log in again. Unsynced cash entries on this phone: 0.',ok:'Log out',act:'logout',cancel:'Stay logged in'});

// ---------- PROPERTIES ----------
def('propList',{t:'Properties',m:M2,r:'owner',tab:'propList',code:'P-01',d:'All properties (branches) in the business, across cities. Shows occupancy at a glance. Tap a property to manage its buildings, rooms, beds, amenities, photos, documents and rules.',try:['Tap Royal PG.','Tap “Bed map” for the visual occupancy overview.','Tap “Add property”.'],
 empty:{icon:'bldg',title:'No properties yet',msg:'Add your first PG to start adding rooms and residents.',cta:'Add property',go:'propForm'},
 v:()=>{const b=DB.beds,o=b.filter(x=>x.status==='Occupied').length;return page({sub:`${DB.props.length} properties · ${new Set(DB.props.map(p=>p.city)).size} cities`,right:`<button class="ib" data-go="occMap" aria-label="Bed map">${ic('grid')}</button>`,fab:['Add property',{go:'propForm'}],body:`
 <div class="g3">${[['Buildings',DB.blds.length],['Rooms',DB.rooms.length],['Beds',b.length]].map(([l,v])=>card(`<div class="t-l w7">${v}</div><div class="t-xs mut">${l}</div>`,'',{style:'text-align:center;padding:10px'})).join('')}</div>
 ${card(`<div class="between"><b>${pct(o,b.length)}% occupied overall</b><span class="lnk" data-go="occMap">Bed map</span></div><div style="margin-top:8px">${bedStack({occ:o,res:b.filter(x=>x.status==='Reserved').length,av:b.filter(x=>x.status==='Available').length,mn:b.filter(x=>x.status==='Maintenance').length,ina:b.filter(x=>x.status==='Inactive').length})}</div>`)}
 ${DB.props.map(P=>{const pb=b.filter(x=>x.propId===P.id),po=pb.filter(x=>x.status==='Occupied').length;return card(`${illus(P,86,`<span class="bdg" style="background:#fff;color:var(--ink)">${P.gender}</span>${sb(P.status)}`)}<div class="between" style="margin-top:10px"><div><div class="w7 t-l">${P.name}</div><div class="t-s mut">${ic('pin','sm')} ${P.area}, ${P.city}</div></div><div style="text-align:right"><div class="w7 t-l">${pct(po,pb.length)}%</div><div class="t-xs mut">occupied</div></div></div><div class="g4" style="margin-top:10px;text-align:center">${[['Bldgs',DB.blds.filter(x=>x.propId===P.id).length],['Rooms',DB.rooms.filter(x=>x.propId===P.id).length],['Beds',pb.length],['Free',pb.filter(x=>x.status==='Available').length]].map(([l,v])=>`<div><div class="w7">${v}</div><div class="t-xs mut">${l}</div></div>`).join('')}</div>`,'',{go:'propDetail',p:{id:P.id}})}).join('')}<div style="height:50px"></div>`})}});

def('propDetail',{t:'Property details',m:M2,r:'owner',tab:'propList',code:'P-02',dp:{id:'p1'},d:'Everything about one property in tabs: overview & analytics, buildings, amenities, photos, documents (with expiry reminders) and PG rules (curfew, visitor policy). The pencil edits the property.',try:['Switch between the tabs.','Open Buildings → Block A to drill down to rooms and beds.','Open the Documents tab on Royal PG to see an expiring Fire NOC.'],
 v:p=>{const P=PR(p.id),t=U(K('pt'),p.t||'ov'),pb=DB.beds.filter(x=>x.propId===P.id),pi=DB.inv.filter(i=>i.propId===P.id),pe=DB.exp.filter(e=>e.propId===P.id);
 const s={occ:pb.filter(x=>x.status==='Occupied').length,res:pb.filter(x=>x.status==='Reserved').length,av:pb.filter(x=>x.status==='Available').length,mn:pb.filter(x=>x.status==='Maintenance').length,ina:pb.filter(x=>x.status==='Inactive').length};
 let body='';
 if(t==='ov') body=`<div class="g4" style="text-align:center">${[['Bldgs',DB.blds.filter(x=>x.propId===P.id).length],['Rooms',DB.rooms.filter(x=>x.propId===P.id).length],['Beds',pb.length],['Occ.',pct(s.occ,pb.length)+'%']].map(([l,v])=>card(`<div class="w7 t-l">${v}</div><div class="t-xs mut">${l}</div>`,'',{style:'padding:9px 2px'})).join('')}</div>
  ${card(`<div class="between"><b>Bed status</b><span class="lnk" data-go="occMap" data-p="pid:${P.id}">Open bed map</span></div><div style="margin:8px 0">${bedStack(s)}</div><div class="t-s" style="display:grid;grid-template-columns:1fr 1fr;gap:3px">${Object.entries({Occupied:s.occ,Available:s.av,Reserved:s.res,Maintenance:s.mn}).map(([k,v])=>`<span><b>${v}</b> <span class="mut">${k}</span></span>`).join('')}</div>`)}
  <div class="g2">${stat('Collected · Dec',inr(sum(pi,i=>i.paid)),'of '+inr(sum(pi,i=>i.total)),'var(--green)')}${stat('Expenses',inr(sum(pe,e=>e.amt)),'Last 30 days')}</div>
  ${card(`<div class="between"><b>Status</b>${sb(P.status)}</div><div class="t-s mut" style="margin-top:4px">Inactive properties are hidden from reservations and new allocations.</div>`)}
  ${sec('Contact & location')}${card(kv([['Type',P.ptype+' · '+P.gender],['Address',`${P.addr}, ${P.city}, ${P.state} ${P.pin}`],['Contact',P.phone],['Email',P.email],['Curfew',P.curfew]])+`<div class="map" style="margin-top:10px">${ic('pin','lg pin')}</div><div class="t-s lnk" style="margin-top:6px">${ic('pin','sm')} Open in Google Maps</div>`)}
  ${sec('About')}${card(`<div class="t-m mut">${P.desc}</div>`)}
  ${btn('View property analytics',{k:'s',icon:'chart',go:'report',p:{id:'compare'}})}`;
 if(t==='bld') body=list(DB.blds.filter(x=>x.propId===P.id).map(B=>{const bb=pb.filter(x=>x.bldId===B.id);return li({icon:'bldg',bg:'var(--blue-50)',fg:'var(--blue)',title:B.name,sub:`${B.floors} floors · ${DB.rooms.filter(r=>r.bldId===B.id).length} rooms · ${bb.length} beds`,right:`<b>${pct(bb.filter(x=>x.status==='Occupied').length,bb.length)}%</b><span class="t-xs mut">${bb.filter(x=>x.status==='Available').length} free</span>`,go:'bldDetail',p:{id:B.id}})}))+btn('Add building',{k:'s',icon:'plus',go:'bldForm',p:{pid:P.id}});
 if(t==='am'){const all=['Wi-Fi','AC rooms','RO water','Meals','Washing machine','Power backup','CCTV','Housekeeping','Geyser','Gym','Lift','Parking (2-wheeler)','Common kitchen','Biometric entry','Lady warden','Study room','Refrigerator','TV lounge'];if(!ST.f['am_'+P.id])ST.f['am_'+P.id]=[...P.amen];
  body=`<div class="t-s mut">Shown to residents in the app and on invites. Tap to switch on/off.</div>${pick('am_'+P.id,all,{multi:true})}${btn('Save amenities',{act:'saveAmen',p:{id:P.id}})}`;}
 if(t==='ph') body=`<div class="g3">${['Front gate','Room A-201','Mess area','Washroom','Terrace','Common area'].map(x=>`<div><div class="ph">${ic('img','lg')}</div><div class="t-xs mut" style="margin-top:4px;text-align:center">${x}</div></div>`).join('')}</div>${upl('ph_'+P.id,'Upload photos','Room_photo.jpg')}<div class="help">First photo is the cover image. Max 20 photos per property.</div>`;
 if(t==='docs'){const exp=P.id==='p2';body=`${exp?banner('warn','alert','<b>Fire NOC expires on 15 Jan 2027.</b> Upload the renewed certificate to stop reminders.'):''}${list([['Rent / lease agreement','Valid till 31 Mar 2028','ok'],['Fire NOC',exp?'Expires 15 Jan 2027':'Valid till 30 Sep 2027',exp?'warn':'ok'],['Trade licence (Shops & Establishment)','Valid till 31 Mar 2027','ok'],['PG registration with police','Submitted 12 Jan 2026','ok'],['Property tax receipt','FY 2026-27','ok'],['Electricity connection','Consumer no. 1182044573','mute']].map(([n,s,k])=>li({icon:'file',title:n,sub:s,right:bdg(k==='warn'?'Expiring':k==='ok'?'Valid':'On file',k),act:'toast',p:{m:'Opening '+n+' (PDF viewer)'}})))}${upl('doc_'+P.id,'Upload document','Fire_NOC_2027.pdf')}`}
 if(t==='rules') body=`${inp('ru_cur_'+P.id,{l:'Curfew / gate closing time',v:P.curfew,icon:'clock'})}${inp('ru_vis_'+P.id,{l:'Visitor hours',v:'9:00 AM – 8:00 PM, common area only'})}
  ${list([togRow('ru_on_'+P.id,'Overnight guests allowed','Off = not permitted',false),togRow('ru_sm_'+P.id,'Smoking & alcohol prohibited','Shown in house rules',true),togRow('ru_pv_'+P.id,'Police verification mandatory','Required before check-in',true)])}
  <div class="g2">${inp('ru_np_'+P.id,{l:'Notice period',v:'30 days'})}${inp('ru_dr_'+P.id,{l:'Deposit refund in',v:'7 days'})}</div>
  ${ta('ru_txt_'+P.id,{l:'Other rules',v:'Quiet hours 10:30 PM – 7 AM. Switch off AC and lights when leaving the room. Cooking not allowed in rooms. Lost key: ₹300.'})}${btn('Save rules',{act:'toast',p:{m:'Rules saved · residents notified'}})}`;
 return page({title:P.name,sub:`${P.city} · ${P.gender}`,right:`<button class="ib" data-go="propForm" data-p="id:${P.id}" aria-label="Edit">${ic('edit')}</button>`,body:`${illus(P,110,`<span class="bdg" style="background:#fff;color:var(--ink)">${ic('pin','sm')}${P.area}</span>${sb(P.status)}`)}
 ${tabsBar(K('pt'),[['ov','Overview'],['bld','Buildings'],['am','Amenities'],['ph','Photos'],['docs','Documents'],['rules','Rules']],p.t||'ov')}${body}`})}});
A.saveAmen=p=>{PR(p.id).amen=[...F('am_'+p.id,[])];toast('Amenities saved')};

def('propForm',{t:'Add / edit property',m:M2,r:'owner',tab:'propList',code:'P-03',d:'Create a new property or edit an existing one. Address, PIN, map pin, gender type and status. Status “Inactive” hides it from new allocations without deleting history.',try:['Tap Save with empty fields to see validation.','Type a 5-digit PIN.'],data:'Plan limit check: Professional allows 5 properties (3 used). A 6th would show an upgrade prompt.',
 v:p=>{const P=p.id?PR(p.id):null,x=P?'pe'+P.id+'_':'pn_';return page({title:P?'Edit property':'Add property',close:!P,body:`
 ${inp(x+'n',{l:'Property name',v:P?.name,ph:'e.g. Shanti Girls PG',req:true,msg:'Enter the property name'})}
 ${sel(x+'t',['PG','Hostel','Co-living','Service apartment'],{l:'Property type',v:P?.ptype||'PG'})}
 ${pick(x+'g',['Boys','Girls','Co-living'],{l:'Gender type',v:P?.gender,req:true})}
 ${inp(x+'a',{l:'Address',v:P?.addr,ph:'Building, street, area',req:true,msg:'Enter the address'})}
 <div class="g2">${inp(x+'c',{l:'City',v:P?.city,req:true,msg:'Enter city'})}${sel(x+'s',['Gujarat','Maharashtra','Karnataka','Rajasthan','Madhya Pradesh','Delhi','Telangana','Tamil Nadu','Uttar Pradesh'],{l:'State',v:P?.state||'Gujarat'})}</div>
 ${inp(x+'pin',{l:'PIN code',v:P?.pin,im:'numeric',max:6,req:true,pat:'[1-9][0-9]{5}',msg:'PIN code must be 6 digits'})}
 <div class="map">${ic('pin','lg pin')}<span class="bdg b-mute" style="position:absolute;left:8px;bottom:8px;background:#fff">Drag pin to the gate · Google Maps</span></div>
 ${inp(x+'ph',{l:'Contact number',v:P?P.phone.replace('+91 ',''):'',pre:'+91',im:'numeric',req:true,pat:'[6-9][0-9]{9}',msg:'Enter a valid 10-digit mobile number'})}
 ${inp(x+'e',{l:'Email',v:P?.email,type:'email',pat:'[^@]+@[^@]+\\.[a-z]{2,}',msg:'Enter a valid email'})}
 ${ta(x+'d',{l:'Description',v:P?.desc,ph:'What makes this PG special? Nearby colleges/offices…'})}
 ${pick(x+'st',['Active','Under setup','Inactive'],{l:'Status',v:P?.status||'Under setup'})}`,foot:btn(P?'Save changes':'Create property',{act:'saveProp',p:{id:p.id||'',x}})})}});
A.saveProp=p=>{const x=p.x;if(!validate([x+'n',x+'g',x+'a',x+'c',x+'pin',x+'ph',x+'e']))return;
 if(p.id){const P=PR(p.id);Object.assign(P,{name:F(x+'n'),gender:F(x+'g'),addr:F(x+'a'),city:F(x+'c'),pin:F(x+'pin'),status:F(x+'st',P.status),desc:F(x+'d',P.desc)});back();toast('Property updated')}
 else{if(DB.props.length>=5){confirmD({icon:'star',title:'Upgrade to add more properties',msg:'Professional allows 5 properties. Upgrade to Enterprise for unlimited properties.',ok:'See plans',act:'goPlans'});return}
  const id='p'+(DB.props.length+1);DB.props.push({id,name:F(x+'n'),short:F(x+'n').split(' ')[0],code:initials(F(x+'n')),city:F(x+'c'),state:F(x+'s','Gujarat'),pin:F(x+'pin'),area:F(x+'a').split(',').pop().trim(),addr:F(x+'a'),gender:F(x+'g'),ptype:F(x+'t','PG'),phone:'+91 '+F(x+'ph'),email:F(x+'e',''),bg:'#E3F4EA',fg:'#11683A',amen:['Wi-Fi'],status:F(x+'st','Under setup'),curfew:'10:00 PM',desc:F(x+'d',''),base:0});clearF(x);rep('propDetail',{id,t:'bld'});toast('Property created · now add a building')}};
A.goPlans=()=>{closeOv();go('plans')};

def('bldDetail',{t:'Building & floors',m:M3,r:'owner',tab:'propList',code:'P-04',dp:{id:'p1b0'},d:'One building shown floor by floor. Each room card shows its beds as coloured squares so availability is visible without opening anything.',try:['Tap any room card to see its beds.','Tap “Add room”.'],
 v:p=>{const B=BL(p.id),P=PR(B.propId),rooms=DB.rooms.filter(r=>r.bldId===B.id),f=U(K('fl'),'all');const fl=[...new Set(rooms.map(r=>r.floor))];
 return page({title:B.name,sub:P.name,right:`<button class="ib" data-act="sheet" data-p="s:bldMenu,id:${B.id}" aria-label="More">${ic('dots')}</button>`,body:`
 ${chips(K('fl'),[['all','All floors'],...fl.map(x=>[String(x),x===0?'Ground':`Floor ${x}`])],'all',{scroll:true})}
 ${fl.filter(x=>f==='all'||String(x)===f).map(x=>`${sec(`Floor ${x}`,`${rooms.filter(r=>r.floor===x).length} rooms`)}<div class="g2">${rooms.filter(r=>r.floor===x).map(R=>{const bs=DB.beds.filter(b=>b.roomId===R.id);return card(`<div class="between"><b>${R.no}</b>${R.ac?bdg('AC','info'):bdg('Non-AC','mute')}</div><div class="t-xs mut" style="margin:3px 0 8px">${R.type} · ${inr(R.rent)}</div><div class="dotrow">${bs.map(b=>`<i class="d-${b.status}" title="${b.status}"></i>`).join('')}</div><div class="t-xs mut" style="margin-top:6px">${bs.filter(b=>b.status==='Available').length} of ${bs.length} free</div>`,'',{go:'roomDetail',p:{id:R.id}})}).join('')}</div>`).join('')}
 <div class="g2">${btn('Add floor',{k:'s',icon:'plus',act:'addFloor',p:{id:B.id}})}${btn('Add room',{k:'s',icon:'plus',go:'roomForm',p:{bid:B.id}})}</div>`})}});
SH.bldMenu=p=>`<b class="t-l">${BL(p.id).name}</b>${list([li({icon:'edit',title:'Edit building',act:'toast',p:{m:'Building details opened for editing'}}),li({icon:'plus',title:'Add floor',act:'addFloor',p:{id:p.id}}),li({icon:'grid',title:'Open bed map',go:'occMap',p:{pid:BL(p.id).propId}}),li({icon:'trash',fg:'var(--red)',bg:'var(--red-50)',title:'<span class="c-err">Delete building</span>',sub:'Only possible when no beds are occupied',act:'toast',p:{m:'Can’t delete: 39 beds are occupied'}})])}`;
A.addFloor=p=>{const B=BL(p.id);B.floors++;const f=B.floors;[1,2,3].forEach((x,i)=>{const R={id:'rm'+DB.rooms.length,propId:B.propId,bldId:B.id,floor:f,no:`${B.code}-${f}0${i+1}`,share:3,ac:true,bath:'Common',rent:8000,status:'Active',type:'3 sharing',meterPrev:0,meterCur:0};DB.rooms.push(R);for(let k=0;k<3;k++)DB.beds.push({id:'bd'+DB.beds.length,roomId:R.id,propId:B.propId,bldId:B.id,label:'ABC'[k],status:'Available'})});closeOv();render();toast(`Floor ${f} added with 3 rooms · 9 beds`)};

def('bldForm',{t:'Add building',m:M3,r:'owner',tab:'propList',code:'P-05',dp:{pid:'p1'},d:'Adds a building (block/tower/wing) to a property. Optionally auto-creates floors and rooms like the onboarding quick setup.',try:['Tap Save without a name.'],
 v:p=>page({title:'Add building',sub:PR(p.pid).name,close:true,body:`${inp('bf_n',{l:'Building name',ph:'e.g. Block C / Tower 3',req:true,msg:'Enter a building name'})}${inp('bf_c',{l:'Short code (used in room numbers)',ph:'C',max:3,req:true,msg:'Enter a short code like C or T3'})}
 <div class="g2">${inp('bf_f',{l:'Floors',v:'3',im:'numeric'})}${inp('bf_r',{l:'Rooms per floor',v:'4',im:'numeric'})}</div>${pick('bf_s',['1','2','3','4'],{l:'Default sharing',v:'2'})}${list([togRow('bf_lift','Lift available','',false),togRow('bf_auto','Create rooms & beds now','You can edit each later',true)])}`,foot:btn('Save building',{act:'saveBld',p:{pid:p.pid}})})});
A.saveBld=p=>{if(!validate(['bf_n','bf_c']))return;const id=p.pid+'b'+DB.blds.length;const fl=+F('bf_f',3),rp=+F('bf_r',4),sh=+F('bf_s','2'),code=F('bf_c').toUpperCase();DB.blds.push({id,propId:p.pid,code,name:F('bf_n'),floors:fl});
 if(F('bf_auto',true))for(let f=1;f<=fl;f++)for(let i=1;i<=rp;i++){const R={id:'rm'+DB.rooms.length,propId:p.pid,bldId:id,floor:f,no:`${code}-${f}0${i}`,share:sh,ac:true,bath:sh<=2?'Attached':'Common',rent:RENT[sh]||8000,status:'Active',type:sh+' sharing',meterPrev:0,meterCur:0};DB.rooms.push(R);for(let k=0;k<sh;k++)DB.beds.push({id:'bd'+DB.beds.length,roomId:R.id,propId:p.pid,bldId:id,label:'ABCD'[k],status:'Available'})}
 clearF('bf_');rep('bldDetail',{id});toast('Building added')};

def('roomDetail',{t:'Room details',m:M3,r:'owner',tab:'propList',code:'P-06',dp:{id:'rm5'},d:'A room with its beds laid out visually. Each bed shows its status and the resident’s first name. Also holds the room’s electricity meter, used to split the bill among the beds.',try:['Tap a green (available) bed to allocate or reserve it.','Tap “Add reading” to enter a new meter reading.'],
 v:p=>{const R=RM(p.id),B=BL(R.bldId),P=PR(R.propId),bs=DB.beds.filter(b=>b.roomId===R.id),units=R.meterCur-R.meterPrev,occ=bs.filter(b=>b.status==='Occupied').length||1;
 return page({title:'Room '+R.no,sub:`${P.short} · ${B.name} · Floor ${R.floor}`,right:`<button class="ib" data-go="roomForm" data-p="id:${R.id}" aria-label="Edit">${ic('edit')}</button>`,body:`
 <div class="chips">${bdg(R.type,'navy')}${R.ac?bdg('AC','info'):bdg('Non-AC','mute')}${bdg(R.bath+' bathroom','mute')}${sb(R.status)}</div>
 ${card(kv([['Monthly rent per bed',inr(R.rent)],['Sharing capacity',R.share+' beds'],['Occupied',`${bs.filter(b=>b.status==='Occupied').length} of ${bs.length}`]]))}
 ${sec('Beds','Tap a bed')}<div class="bedgrid">${bs.map(b=>{const r=resOnBed(b.id);return `<div class="bed ${b.status}" data-go="bedDetail" data-p="id:${b.id}" role="button" tabindex="0">${ic('bed')}<span>Bed ${b.label}</span><span class="t-xs" style="font-weight:500;opacity:.85">${r?r.first:b.status}</span></div>`}).join('')}</div>
 ${sec('Electricity meter')}${card(`${kv([['Previous reading (1 Nov)',R.meterPrev.toLocaleString('en-IN')+' kWh'],['Current reading (1 Dec)',R.meterCur.toLocaleString('en-IN')+' kWh'],['Units used',units+' units'],['Rate','₹9.00 / unit'],['Room total',inr(units*9)],['Share per occupied bed',inr(units*9/occ)]])}<div class="row" style="margin-top:10px">${btn('Add reading',{k:'s',sm:true,icon:'bolt',act:'sheet',p:{s:'meter',id:R.id}})}${btn('History',{k:'g',sm:true,act:'toast',p:{m:'Meter history: last 12 readings'}})}</div>`)}
 ${sec('Room amenities')}<div class="chips">${['Bed + mattress','Study table','Wardrobe','Fan',R.ac?'AC':'Cooler','Geyser'].map(x=>bdg(x,'mute')).join('')}</div>`})}});
SH.meter=p=>{const R=RM(p.id);return `<b class="t-l">New meter reading · ${R.no}</b>${inp('mr_v',{l:'Current reading (kWh)',ph:String(R.meterCur+120),im:'numeric',req:true,pat:'[0-9]+',msg:'Enter the meter reading in numbers'})}${inp('mr_d',{l:'Reading date',type:'date',v:'2026-12-02'})}${upl('mr_ph','Photo of meter (optional)','meter_A201.jpg')}${btn('Save reading',{act:'saveMeter',p:{id:R.id}})}`};
A.saveMeter=p=>{if(!validate(['mr_v']))return;const R=RM(p.id),v=+F('mr_v');if(v<=R.meterCur){ST.err.mr_v=`Must be more than the last reading (${R.meterCur})`;render();return}R.meterPrev=R.meterCur;R.meterCur=v;clearF('mr_');closeOv();render();toast('Reading saved · bill split updated')};

def('roomForm',{t:'Add / edit room',m:M3,r:'owner',tab:'propList',code:'P-07',dp:{bid:'p1b0'},d:'Room setup: number, floor, type, sharing (which sets the number of beds), rent, AC, bathroom and amenities.',try:['Change sharing to see how many beds will be created.'],
 v:p=>{const R=p.id?RM(p.id):null,B=BL(R?R.bldId:p.bid),x=R?'re'+R.id+'_':'rn_';return page({title:R?'Edit room '+R.no:'Add room',sub:B.name,close:!R,body:`
 <div class="g2">${inp(x+'no',{l:'Room number',v:R?.no,ph:B.code+'-104',req:true,msg:'Enter room number'})}${sel(x+'fl',Array.from({length:B.floors},(_,i)=>[String(i+1),'Floor '+(i+1)]),{l:'Floor',v:String(R?.floor||1)})}</div>
 ${pick(x+'sh',[['1','Single'],['2','2 sharing'],['3','3 sharing'],['4','4 sharing']],{l:'Sharing capacity',v:String(R?.share||3),h:R?'Changing sharing adds or removes empty beds only':'Creates this many beds automatically'})}
 ${inp(x+'rent',{l:'Monthly rent per bed',pre:'₹',v:R?R.rent.toLocaleString('en-IN'):'8,000',im:'numeric',req:true})}
 ${pick(x+'ac',['AC','Non-AC'],{l:'Cooling',v:R?(R.ac?'AC':'Non-AC'):'AC'})}${pick(x+'bt',['Attached','Common'],{l:'Bathroom',v:R?.bath||'Common'})}
 ${pick(x+'am',['Study table','Wardrobe','Geyser','Balcony','Fridge','TV'],{l:'Amenities',multi:true,v:['Study table','Wardrobe']})}
 ${pick(x+'st',['Active','Maintenance','Inactive'],{l:'Room status',v:R?.status||'Active'})}`,foot:btn(R?'Save room':'Create room',{act:'saveRoom',p:{id:p.id||'',bid:B.id,x}})})}});
A.saveRoom=p=>{const x=p.x;if(!validate([x+'no',x+'rent']))return;const sh=+F(x+'sh','3'),rent=+String(F(x+'rent','8000')).replace(/\D/g,'');
 if(p.id){const R=RM(p.id);Object.assign(R,{no:F(x+'no',R.no),rent,ac:F(x+'ac')!=='Non-AC',bath:F(x+'bt',R.bath),status:F(x+'st',R.status)});back();toast('Room updated');return}
 const B=BL(p.bid),R={id:'rm'+DB.rooms.length,propId:B.propId,bldId:B.id,floor:+F(x+'fl','1'),no:F(x+'no'),share:sh,ac:F(x+'ac','AC')==='AC',bath:F(x+'bt','Common'),rent,status:'Active',type:sh===1?'Single':sh+' sharing',meterPrev:0,meterCur:0};DB.rooms.push(R);for(let k=0;k<sh;k++)DB.beds.push({id:'bd'+DB.beds.length,roomId:R.id,propId:B.propId,bldId:B.id,label:'ABCD'[k],status:'Available'});clearF(x);rep('roomDetail',{id:R.id});toast(`Room ${R.no} created with ${sh} bed${sh>1?'s':''}`)};

def('bedDetail',{t:'Bed details',m:M3,r:'owner',tab:'propList',code:'P-08',dp:{id:'bd0'},d:'One bed: current status, who is on it, any reservation, and the full allocation history. Actions change with the status (allocate, reserve, mark maintenance, check out).',try:['On an available bed, tap “Mark under maintenance” and see the room view update.','On an occupied bed, open the resident.'],
 v:p=>{const b=BD(p.id),R=RM(b.roomId),P=PR(b.propId),r=resOnBed(b.id),rv=DB.resv.find(x=>x.bedId===b.id&&['Confirmed','Pending payment'].includes(x.status));
 const acts={Available:[btn('Allocate to resident',{icon:'users',go:'resAdd',p:{bed:b.id}}),btn('Reserve bed',{k:'s',icon:'cal',go:'resvCreate',p:{bed:b.id}}),btn('Mark under maintenance',{k:'g',act:'bedSt',p:{id:b.id,s:'Maintenance'}})],
  Occupied:[btn('View resident',{go:'resProfile',p:{id:r?.id}}),btn('Start check-out',{k:'s',icon:'out',go:'checkout',p:{id:r?.id}})],
  Reserved:[btn('View reservation',{go:'resvDetail',p:{id:rv?.id}})],
  Maintenance:[btn('Mark available',{k:'ok',icon:'check',act:'bedSt',p:{id:b.id,s:'Available'}}),btn('Raise maintenance task',{k:'s',go:'compList'})],
  Inactive:[btn('Activate bed',{icon:'check',act:'bedSt',p:{id:b.id,s:'Available'}})]}[b.status];
 const hist=[r?[r.name,`${r.join} – present`]:null,['Nirmal Joshi','Aug 2024 – May 2025'],['Vishal Thakkar','Jun 2023 – Jul 2024']].filter(Boolean);
 return page({title:`${R.no} · Bed ${b.label}`,sub:`${P.name} · ${R.type}`,body:`
 <div class="bed ${b.status}" style="min-height:90px;cursor:default">${ic('bed','lg')}<span class="t-l">${b.status}</span><span class="t-xs" style="font-weight:500">${inr(R.rent)} / month · ${R.ac?'AC':'Non-AC'}</span></div>
 ${r?card(`${lbl('Current resident')}<div class="row" style="margin-top:8px"><div class="av">${initials(r.name)}</div><div style="flex:1"><div class="w7">${r.name}</div><div class="t-s mut">Since ${r.join} · ${r.mobile}</div></div>${sb(r.status)}</div>`,'',{go:'resProfile',p:{id:r.id}}):''}
 ${rv?card(`${lbl('Reservation')}<div class="w7" style="margin-top:6px">${rv.name}</div><div class="t-s mut">Check-in ${rv.from} · advance ${inr(rv.advance)}</div>`,'',{go:'resvDetail',p:{id:rv.id}}):''}
 ${b.status==='Maintenance'?banner('warn','wrench','Blocked for repairs. Not offered for allocation or reservation.'):''}
 <div class="stack">${acts.join('')}</div>
 ${sec('Allocation history')}${list(hist.map(([n,s],i)=>li({icon:'user',title:n,sub:s,right:i===0&&r?bdg('Current','navy'):bdg('Past','mute')})))}`})}});
A.bedSt=p=>{BD(p.id).status=p.s;render();toast('Bed marked '+p.s.toLowerCase())};

def('occMap',{t:'Bed map (occupancy)',m:M3,r:'owner',tab:'propList',code:'P-09',d:'Every bed in the selected scope on one screen, grouped by property → building → floor → room. Filter by status to find available, reserved, occupied, maintenance or inactive beds instantly.',try:['Tap the “Available” chip to see only free beds.','Tap any bed to open it.','Switch property with the chip at the top.'],
 v:p=>{if(p.pid&&!ST.ui[K('omInit')]){ST.ui[K('omInit')]=1;ST.ui[K('omP')]=p.pid}const pid=U(K('omP'),ST.prop),f=U(K('omF'),'all');const props=DB.props.filter(P=>pid==='all'||P.id===pid);const bs=DB.beds.filter(b=>pid==='all'||b.propId===pid);const cnt=s=>bs.filter(b=>b.status===s).length;
 return page({sub:pid==='all'?'All Properties':PR(pid).name,body:`${seg(K('omP'),[['all','All'],...DB.props.map(P=>[P.id,P.short])],pid)}
 ${chips(K('omF'),[['all','All',bs.length],['Available','Available',cnt('Available')],['Reserved','Reserved',cnt('Reserved')],['Occupied','Occupied',cnt('Occupied')],['Maintenance','Maint.',cnt('Maintenance')],['Inactive','Inactive',cnt('Inactive')]],'all',{scroll:true})}
 ${props.map(P=>DB.blds.filter(B=>B.propId===P.id).map(B=>{const rooms=DB.rooms.filter(R=>R.bldId===B.id).filter(R=>f==='all'||DB.beds.some(b=>b.roomId===R.id&&b.status===f));if(!rooms.length)return '';return `${sec(`${P.short} · ${B.name}`,`${rooms.length} rooms`)}${card(rooms.map(R=>`<div class="row" style="padding:6px 0;border-bottom:1px solid var(--stroke)"><span class="t-s w7" style="width:56px">${R.no}</span><div class="row" style="gap:5px;flex-wrap:wrap">${DB.beds.filter(b=>b.roomId===R.id).map(b=>`<span class="bed ${b.status} ${f!=='all'&&b.status!==f?'blk':''}" style="min-height:0;padding:5px 8px;border-radius:8px" data-go="bedDetail" data-p="id:${b.id}" role="button" tabindex="0" title="${b.status}">${b.label}</span>`).join('')}</div><span class="t-xs mut" style="margin-left:auto">${inr(R.rent)}</span></div>`).join(''),'',{style:'padding:6px 12px'})}`}).join('')).join('')||emptyB({icon:'bed',title:'No beds match this filter',msg:'Try another status.'})}`})}});

// ---------- RESIDENTS ----------
def('resList',{t:'Residents',m:M4,r:'owner',tab:'resList',code:'R-01',d:'All residents in the selected property scope with live search and filters (notice period, KYC pending, rent due, overdue). Reservations are one tap away at the top.',try:['Type “Rohan” in search.','Tap the “KYC pending” chip.','Tap “Add resident” to start the 5-step form.'],
 empty:{icon:'users',title:'No residents added yet',msg:'Add your first resident to start tracking rent and KYC.',cta:'Add resident',go:'resAdd'},
 v:p=>{const q=(F('q_res','')||'').toLowerCase(),f=U(K('rf'),p.f||'all'),all=sRes();
 const test={all:()=>true,active:r=>r.status==='Active',notice:r=>r.status==='Notice',kyc:r=>r.kyc!=='Verified'||r.police!=='Verified',due:r=>{const i=resInv(r.id);return i&&i.status!=='Paid'},overdue:r=>resInv(r.id)?.status==='Overdue'};
 const rs=all.filter(test[f]).filter(r=>!q||(r.name+' '+r.mobile+' '+loc(r)).toLowerCase().includes(q));const lim=U(K('rlim'),30);
 const up=DB.resv.filter(r=>inS(r.propId)&&['Confirmed','Pending payment'].includes(r.status)).length;
 return page({chip:true,sub:`${all.length} residents`,fab:['Add resident',{go:'resAdd'}],body:`
 ${inp('q_res',{ph:'Search name, room or mobile',icon:'search',live:true})}
 ${chips(K('rf'),[['all','All',all.length],['active','Active',all.filter(test.active).length],['notice','Notice period',all.filter(test.notice).length],['kyc','KYC pending',all.filter(test.kyc).length],['due','Rent due',all.filter(test.due).length],['overdue','Overdue',all.filter(test.overdue).length]],p.f||'all',{scroll:true})}
 ${card(`<div class="row"><div class="tile" style="background:var(--violet-50);color:var(--violet)">${ic('cal')}</div><div style="flex:1"><div class="w7">Reservations</div><div class="t-s mut">${up} upcoming check-ins · ${DB.wait.filter(w=>inS(w.propId)).length} on waitlist</div></div>${ic('right','sm mut2')}</div>`,'',{go:'resvList'})}
 ${rs.length?list(rs.slice(0,lim).map(r=>{const i=resInv(r.id);return li({av:initials(r.name),avs:r.status==='Notice'?'background:var(--amber-50);color:var(--amber)':'',title:r.name,sub:loc(r),sub2:r.kyc!=='Verified'?`<span class="c-warn w6">KYC ${r.kyc.toLowerCase()}</span>`:r.status==='Notice'?`<span class="c-warn w6">Leaving ${r.checkout}</span>`:r.mobile,right:`<span class="w7 num">${inr(i.total-i.paid||r.rent)}</span>${sb(i.status)}`,go:'resProfile',p:{id:r.id}})}))+(rs.length>lim?btn(`Show all ${rs.length}`,{k:'g',act:'ui',p:{k:K('rlim'),v:999}}):''):emptyB({icon:'search',bg:'var(--slate-50)',fg:'var(--ink-2)',title:q?`No results for “${esc(q)}”`:'No residents in this filter',msg:'Try another name, room number or mobile number.'})}<div style="height:50px"></div>`})}});

def('resProfile',{t:'Resident profile',m:M4,r:'owner',tab:'resList',code:'R-02',dp:{id:'r1'},pre:()=>{S.resProfile.dp={id:DB.me}},d:'Single place for a resident: personal, guardian & emergency details, KYC and police verification, room allocation, rent and payment history, deposit and stay history. Check-out starts from here.',try:['Switch tabs: Details, KYC, Rent, Stay.','Tap “Check-out” to run the settlement flow.','Tap WhatsApp to see the reminder template.'],
 v:p=>{const r=RS(p.id)||ME(),t=U(K('rt'),'det'),b=BD(r.bedId),R=RM(b.roomId),B=BL(R.bldId),P=PR(r.propId),i=resInv(r.id);let body='';
 if(t==='det') body=`${sec('Personal')}${card(kv([['Mobile',r.mobile],['Email',r.email],['Date of birth',r.dob],['Gender',r.gender],['Occupation',r.occ],[r.occ==='Student'?'College':'Company',r.org],['Permanent address',r.addr],['Current address',`${P.name}, ${P.city}`]]))}
  ${sec('Guardian')}${card(kv([['Name',r.guardian.name],['Relation',r.guardian.rel],['Mobile',r.guardian.mobile]]))}
  ${sec('Emergency contact')}${card(kv([['Name',r.emergency.name],['Relation',r.emergency.rel],['Mobile',r.emergency.mobile]]))}
  ${sec('Room allocation','Change bed',{act:'sheet',p:{s:'chBed',id:r.id}})}${card(kv([['Property',P.name],['Building',B.name],['Floor','Floor '+R.floor],['Room',R.no+' · '+R.type],['Bed','Bed '+b.label],['Joined',r.join],['Monthly rent',inr(r.rent)],['Security deposit',inr(r.deposit)],['Meal plan',r.mess?'Full veg plan · ₹3,200':'None']]))}`;
 if(t==='kyc') body=`${card(`<div class="between"><b>Identity (KYC)</b>${sb(r.kyc)}</div><div class="t-s mut" style="margin-top:4px">${r.kycDoc}${r.kycDoc.startsWith('Aadhaar')?' · XXXX XXXX 4821 (masked)':''}</div>${r.kycDoc.includes('DigiLocker')&&r.kyc==='Verified'?`<div class="row t-s c-ok w6" style="margin-top:6px;gap:5px">${ic('shield','sm')}Verified through DigiLocker — full Aadhaar number is never stored</div>`:''}${r.kyc!=='Verified'?`<div style="margin-top:10px">${btn('Review documents',{sm:true,go:'kycVerify',p:{id:r.id}})}</div>`:''}`)}
  ${card(`<div class="between"><b>Police verification</b>${sb(r.police)}</div><div class="t-s mut" style="margin-top:4px">${r.police==='Verified'?'Tenant verification form submitted to local police station · ref VAD/TV/2025/18342':'Required by local rules before or soon after check-in.'}</div>${r.police!=='Verified'?`<div class="row" style="margin-top:10px">${btn('Mark submitted',{sm:true,act:'police',p:{id:r.id}})}${btn('Download form',{k:'s',sm:true,act:'toast',p:{m:'Tenant verification form (PDF) ready'}})}</div>`:''}`)}
  ${sec('Documents')}${list([['ID proof · front','Aadhaar (masked) · uploaded '+r.join],['ID proof · back','Uploaded '+r.join],['Passport photo','Uploaded'],[r.occ==='Student'?'College ID card':'Office ID card','Expires 30 Jun 2027']].map(([n,s])=>li({icon:'file',title:n,sub:s,act:'toast',p:{m:'Opening '+n}})))}
  ${banner('info','bell','You’ll be reminded 30 days before any document expires.')}`;
 if(t==='rent'){const pays=DB.pay.filter(x=>x.resId===r.id);body=`${card(`<div class="between">${lbl('Current invoice · '+i.month)}${sb(i.status)}</div><div class="between" style="margin-top:6px"><span class="t-xl w7 num">${inr(i.total-i.paid)}</span><span class="t-s mut">${i.status==='Paid'?'Paid in full':'due '+i.due}</span></div>`,'',{go:'invDetail',p:{id:i.id}})}
  <div class="g2">${btn('Collect payment',{icon:'rupee',go:'payRecord',p:{inv:i.id}})}${btn('Remind',{k:'wa',icon:'whats',act:'sheet',p:{s:'remind',id:r.id}})}</div>
  ${sec('Payment history')}${list([...pays.map(x=>li({icon:'receipt',bg:'var(--green-50)',fg:'var(--green)',title:inr(x.amt)+' · '+x.method,sub:`${x.date} · ${x.ref}`,right:sb(x.status),go:'payDetail',p:{id:x.id}})),...['Nov','Oct','Sep'].map((m,k)=>li({icon:'receipt',bg:'var(--green-50)',fg:'var(--green)',title:inr(r.rent+[430,380,510][k])+' · UPI',sub:`${[3,4,2][k]} ${m} 2026 · Rent ${m} 2026`,right:sb('Success'),act:'toast',p:{m:'Receipt for '+m+' 2026'}}))])}`}
 if(t==='stay') body=`${card(kv([['Joined',r.join],['Stay so far',r.months+' months'],['Status',r.status==='Notice'?'Notice period · leaving '+r.checkout:r.status],['Notice period','30 days']]))}
  ${sec('Deposit','Details',{go:'depDetail',p:{id:r.id}})}${card(`<div class="between"><span class="t-xl w7 num">${inr(r.deposit)}</span>${sb(r.depStatus)}</div><div class="t-s mut">Collected on ${r.join} · Cash</div>`)}
  ${sec('Stay history')}${card(tl([['Checked in · '+R.no+' Bed '+b.label,r.join+' · by Ramesh Parmar','ok'],['KYC verified',r.join,'ok'],...(r.status==='Notice'?[['Notice given','Leaving on '+r.checkout,'on']]:[]),['Next rent due',i.due,'']]))}`;
 return page({title:r.name,sub:loc(r),right:`<button class="ib" data-act="sheet" data-p="s:resMenu,id:${r.id}" aria-label="More">${ic('dots')}</button>`,body:`
 ${card(`<div class="row"><div class="av" style="width:56px;height:56px;font-size:17px">${initials(r.name)}</div><div style="flex:1;min-width:0"><div class="chips">${sb(r.status)}${r.kyc==='Verified'?bdg('KYC verified','ok'):bdg('KYC '+r.kyc.toLowerCase(),'warn')}</div><div class="t-s mut" style="margin-top:5px">${r.occ} · ${r.org}</div></div></div>
 <div class="g3" style="margin-top:12px">${btn('Call',{k:'s',sm:true,icon:'call',act:'toast',p:{m:'Calling '+r.mobile}})}${btn('WhatsApp',{k:'s',sm:true,icon:'whats',act:'sheet',p:{s:'remind',id:r.id}})}${btn('Collect',{k:'s',sm:true,icon:'rupee',go:'payRecord',p:{inv:i.id}})}</div>`)}
 ${tabsBar(K('rt'),[['det','Details'],['kyc','KYC'],['rent','Rent'],['stay','Stay']],'det')}${body}`,foot:r.status!=='Checked out'?btn('Edit',{k:'s',icon:'edit',act:'toast',p:{m:'Edit form opens with the same fields as Add resident'}})+btn('Check-out',{k:'p',icon:'out',go:'checkout',p:{id:r.id}}):''})}});
A.police=p=>{RS(p.id).police='Verified';render();toast('Police verification marked submitted')};
SH.resMenu=p=>{const r=RS(p.id);return `<b class="t-l">${r.name}</b>${list([li({icon:'edit',title:'Edit details',act:'toast',p:{m:'Edit resident form'}}),li({icon:'bed',title:'Change room / bed',act:'sheet',p:{s:'chBed',id:r.id}}),li({icon:'clock',title:'Record notice period',sub:'Sets check-out date',act:'notice',p:{id:r.id}}),li({icon:'out',title:'Start check-out',go:'checkout',p:{id:r.id}}),li({icon:'share',title:'Resend app invite',act:'toast',p:{m:'Invite resent on WhatsApp'}})])}`};
SH.chBed=p=>{const r=RS(p.id),av=DB.beds.filter(b=>b.propId===r.propId&&b.status==='Available').slice(0,9);return `<b class="t-l">Move ${r.first} to another bed</b><div class="t-s mut">Available beds in ${PR(r.propId).name}. Rent updates to the new room’s rate from next invoice.</div><div class="bedgrid">${av.map(b=>`<div class="bed Available" data-act="moveBed" data-p="id:${r.id},b:${b.id}" role="button" tabindex="0">${ic('bed')}<span>${RM(b.roomId).no}</span><span class="t-xs">Bed ${b.label}</span></div>`).join('')}</div>`};
A.moveBed=p=>{const r=RS(p.id),old=BD(r.bedId),nb=BD(p.b);old.status='Available';nb.status='Occupied';r.bedId=nb.id;r.rent=RM(nb.roomId).rent;closeOv();render();toast(`Moved to ${bedName(nb)}`)};
A.notice=p=>{const r=RS(p.id);r.status='Notice';r.checkout='1 Jan 2027';closeOv();render();toast('Notice recorded · check-out 1 Jan 2027')};

SH.remind=p=>{const r=p.id?RS(p.id):null,i=r?resInv(r.id):null;const n=r?1:stats().odCount;return `<b class="t-l">${r?'Send reminder to '+r.first:`Remind ${n} overdue residents`}</b>
 ${pick('rm_ch',['WhatsApp','SMS','Push'],{multi:true,v:['WhatsApp','Push']})}
 ${card(`<div class="row t-s w7" style="color:#1DA851">${ic('whats','sm')}Message preview</div><div class="t-s" style="margin-top:6px">Hi ${r?r.first:'{name}'}, your ${r?i.month:'{month}'} rent of <b>${r?inr(i.total-i.paid):'{amount}'}</b> at ${r?PR(r.propId).name:'{PG name}'} ${r&&i.status!=='Overdue'?'is due on '+i.due:'is overdue'}. Pay in the app: pgerp.in/pay — Thank you.</div>`,'',{style:'background:#E7F7EC;border-color:#CBEBD5'})}
 <div class="help">Approved WhatsApp template · sent from Deven PG Group’s business number</div>${btn('Send reminder',{k:'wa',icon:'whats',act:'toast',p:{m:r?'Reminder sent to '+r.first:`Reminders sent to ${n} residents`}})}`};

// ---------- ADD RESIDENT ----------
const raSteps=['Personal','Guardian','KYC','Room','Rent'];
def('resAdd',{t:'Add resident (5 steps)',m:M4,r:'owner',tab:'resList',code:'R-03',d:'Five short steps instead of one long form: personal → guardian & emergency → KYC → property/room/bed → rent, deposit and invite. Each step validates before moving on. Saving creates the resident, occupies the bed, raises the first invoice and sends the app invite.',try:['Tap Next on an empty step to see validation.','In step 4 tap a grey/blue bed — it can’t be picked.','Finish all steps to see the success screen and invite.'],data:'Aadhaar is never stored in full: either DigiLocker verification or a masked copy with only the last 4 digits.',
 v:p=>{const s=+U(K('ra'),0);if(p.bed&&!F('raBed')){setF({raBed:p.bed,raProp:BD(p.bed).propId})}if(p.name&&!F('raName'))setF({raName:p.name,raMob:p.mob||''});let body='';
 if(s===0) body=`<div class="row">${card(ic('cam','lg'),'',{style:'width:64px;height:64px;border-radius:50%;display:grid;place-items:center;padding:0;color:var(--blue);background:var(--blue-50)',act:'toast',p:{m:'Camera opens to take resident photo'}})}<div><div class="w6">Profile photo</div><div class="t-s mut">Used on ID card & visitor register</div></div></div>
  ${inp('raName',{l:'Full name',ph:'As on ID proof',req:true,msg:'Enter the resident’s full name'})}
  ${inp('raMob',{l:'Mobile number',pre:'+91',im:'numeric',max:10,req:true,pat:'[6-9][0-9]{9}',msg:'Enter a valid 10-digit mobile number',h:'The app invite and OTP go to this number'})}
  ${inp('raEmail',{l:'Email',type:'email',pat:'[^@]+@[^@]+\\.[a-z]{2,}',msg:'Enter a valid email'})}
  <div class="g2">${inp('raDob',{l:'Date of birth',type:'date',req:true,msg:'Select date of birth'})}${sel('raG',['Male','Female','Other'],{l:'Gender',ph:'Select',req:true})}</div>
  ${pick('raOcc',['Student','Working professional'],{l:'Occupation',req:true})}${inp('raOrg',{l:F('raOcc')==='Student'?'College':'Company / College',ph:'e.g. MSU Baroda / TCS'})}${ta('raAddr',{l:'Permanent address',ph:'House, street, city, state, PIN',req:true,msg:'Enter permanent address'})}`;
 if(s===1) body=`${lbl('Guardian')}${inp('raGN',{l:'Guardian name',req:true,msg:'Enter guardian’s name'})}${pick('raGR',['Father','Mother','Brother','Sister','Uncle','Spouse','Other'],{l:'Relation',req:true})}${inp('raGM',{l:'Guardian mobile',pre:'+91',im:'numeric',max:10,req:true,pat:'[6-9][0-9]{9}',msg:'Enter a valid 10-digit mobile number'})}
  ${lbl('Emergency contact')}${list([togRow('raSame','Same as guardian','',false)])}${F('raSame',false)?'':inp('raEN',{l:'Emergency contact name',req:true,msg:'Enter a name'})+inp('raEM',{l:'Emergency mobile',pre:'+91',im:'numeric',max:10,req:true,pat:'[6-9][0-9]{9}',msg:'Enter a valid 10-digit mobile number'})}`;
 if(s===2){const d=F('raDoc','Aadhaar · DigiLocker');body=`${pick('raDoc',['Aadhaar · DigiLocker','Aadhaar · masked copy','PAN card','Passport','Driving licence','Voter ID'],{l:'ID document',v:'Aadhaar · DigiLocker',req:true})}
  ${d==='Aadhaar · DigiLocker'?banner('info','shield','The resident gets a DigiLocker consent link. Only name, DOB, photo and last 4 digits are received — the full Aadhaar number is never stored.')+list([togRow('raDL','Send DigiLocker link to resident','On save, via WhatsApp/SMS',true)]):`${d.startsWith('Aadhaar')?banner('warn','alert','Ask for a masked Aadhaar (first 8 digits hidden). Don’t upload a full Aadhaar copy.'):''}${inp('raRef',{l:d.startsWith('Aadhaar')?'Last 4 digits':'Document number',max:d.startsWith('Aadhaar')?4:20,req:true,pat:d.startsWith('Aadhaar')?'[0-9]{4}':'.{5,20}',msg:d.startsWith('Aadhaar')?'Enter exactly 4 digits':'Enter the document number'})}<div class="g2">${upl('raF','Front side','ID_front.jpg')}${upl('raB','Back side','ID_back.jpg')}</div>${d==='Passport'?inp('raExp',{l:'Expiry date',type:'date',h:'We’ll remind you 30 days before expiry'}):''}`}
  ${list([togRow('raPol','Police verification required','Track submission on the profile',true),togRow('raLater','Resident will upload documents in the app','KYC stays “Pending” until reviewed',false)])}`}
 if(s===3){const pid=F('raProp',ST.prop==='all'?'p1':ST.prop),bs=DB.beds.filter(b=>b.propId===pid),sel_=F('raBed');body=`${sel('raProp',DB.props.map(P=>[P.id,P.name]),{l:'Property',v:pid,live:true})}
  <div class="between">${lbl('Choose a bed')}<span class="t-xs mut">${bs.filter(b=>b.status==='Available').length} available</span></div>
  ${ST.err.raBed?`<div class="help err">${ic('alert','sm')}${ST.err.raBed}</div>`:''}
  <div id="raBed" data-req data-msg="Select an available bed">${DB.blds.filter(B=>B.propId===pid).map(B=>`<div class="t-s w7" style="margin:8px 0 6px">${B.name}</div><div class="bedgrid" style="grid-template-columns:repeat(auto-fill,minmax(58px,1fr))">${DB.beds.filter(b=>b.bldId===B.id).map(b=>`<div class="bed ${b.status} ${b.id===sel_?'sel':''} ${b.status!=='Available'?'blk':''}" data-act="raBed" data-p="id:${b.id}" role="button" tabindex="0" style="min-height:52px;padding:5px 2px"><span>${RM(b.roomId).no}</span><span class="t-xs">Bed ${b.label}</span></div>`).join('')}</div>`).join('')}</div>
  ${sel_?card(`<div class="between"><b>${bedName(BD(sel_))}</b>${bdg('Selected','info')}</div><div class="t-s mut">${RM(BD(sel_).roomId).type} · ${RM(BD(sel_).roomId).ac?'AC':'Non-AC'} · ${inr(RM(BD(sel_).roomId).rent)}/month</div>`):''}
  ${inp('raJoin',{l:'Check-in date',type:'date',v:'2026-12-05',req:true,msg:'Select check-in date'})}`}
 if(s===4){const R=F('raBed')?RM(BD(F('raBed')).roomId):null,rent=+(String(F('raRent',R?R.rent:8000)).replace(/\D/g,''));body=`${inp('raRent',{l:'Monthly rent',pre:'₹',v:R?R.rent:'8000',im:'numeric',req:true,pat:'[0-9]{3,6}',msg:'Enter rent in rupees',h:'Room default: '+(R?inr(R.rent):'—')})}
  ${inp('raDep',{l:'Security deposit',pre:'₹',v:R?R.rent:'8000',im:'numeric',req:true,pat:'[0-9]{3,6}',msg:'Enter deposit amount'})}
  ${pick('raDepM',['Cash','UPI','Collect later'],{l:'Deposit received by',v:'UPI'})}
  ${pick('raMeal',MEALPLANS.map(m=>[m[0],m[0]+(m[2]?` · ${inr(m[2])}`:'')]),{l:'Meal plan',v:'No meal plan'})}
  ${pick('raEl',['Meter share','Fixed ₹500','Included in rent'],{l:'Electricity',v:'Meter share'})}
  ${pick('raInv',['WhatsApp','SMS'],{l:'Send app invite by',multi:true,v:['WhatsApp']})}
  ${card(`${lbl('First invoice (prorated)')}${kv([['Rent 5–31 Dec (27 days)',inr(rent*27/31)],['Security deposit',inr(+String(F('raDep',R?R.rent:8000)).replace(/\D/g,''))],['Total due at check-in',inr(rent*27/31+(+String(F('raDep',R?R.rent:8000)).replace(/\D/g,'')))]])}`)}`}
 if(s===5){const b=BD(F('raBed'));body=`${banner('info','check','Review before saving. Tap a section to change it.')}${[[0,'Personal',`${esc(F('raName'))} · +91 ${esc(F('raMob'))}<br>${esc(F('raOcc',''))} · ${esc(F('raOrg',''))}`],[1,'Guardian & emergency',`${esc(F('raGN'))} (${esc(F('raGR'))}) · +91 ${esc(F('raGM'))}`],[2,'KYC',esc(F('raDoc','Aadhaar · DigiLocker'))+(F('raPol',true)?' · police verification required':'')],[3,'Room & bed',`${PR(b.propId).name} · ${bedName(b)} · from ${fdate(F('raJoin','2026-12-05'))}`],[4,'Rent & invite',`Rent ₹${esc(F('raRent',RM(b.roomId).rent))} · Deposit ₹${esc(F('raDep',RM(b.roomId).rent))} · ${esc(F('raMeal','No meal plan'))}`]].map(([k,t,x])=>card(`<div class="between"><b>${t}</b><span class="lnk">Edit</span></div><div class="t-s mut" style="margin-top:4px">${x}</div>`,'',{act:'ui',p:{k:K('ra'),v:k}})).join('')}`}
 return page({title:'Add resident',sub:s<5?`Step ${s+1} of 5 · ${raSteps[s]}`:'Review',close:true,body:`${s<5?stepper(raSteps,s):''}${body}`,foot:(s>0?btn('Back',{k:'s',act:'ui',p:{k:K('ra'),v:s-1}}):'')+btn(s<4?'Next':s===4?'Review':'Save & send invite',{act:'raNext',p:{s}})})}});
A.raBed=p=>{const b=BD(p.id);if(b.status!=='Available'){toast(b.status==='Reserved'?'This bed is reserved for another resident':'This bed is '+b.status.toLowerCase()+' and can’t be allocated','err');return}ST.f.raBed=p.id;delete ST.err.raBed;render()};
A.raNext=p=>{const s=+p.s,k=K('ra');const req=[['raName','raMob','raEmail','raDob','raG','raOcc','raAddr'],['raGN','raGR','raGM',...(F('raSame',false)?[]:['raEN','raEM'])],[...(F('raDoc','Aadhaar · DigiLocker')!=='Aadhaar · DigiLocker'?['raRef']:[]),'raDoc'],['raJoin'],['raRent','raDep']][s];
 if(s===3&&!F('raBed')){ST.err.raBed='Select an available bed';render();toast('Please select a bed','err');return}
 if(s<5&&!validate(req||[]))return;
 if(s<5){ST.ui[k]=s+1;render(true);return}
 const b=BD(F('raBed')),R=RM(b.roomId),id='r'+(DB.res.length+100),rent=+String(F('raRent',R.rent)).replace(/\D/g,''),dep=+String(F('raDep',R.rent)).replace(/\D/g,'');const nm=F('raName');
 DB.res.push({id,name:nm,first:nm.split(' ')[0],gender:F('raG'),mobile:'+91 '+F('raMob'),email:F('raEmail','—'),dob:fdate(F('raDob')),occ:F('raOcc'),org:F('raOrg','—'),home:'',guardian:{name:F('raGN'),rel:F('raGR'),mobile:'+91 '+F('raGM')},emergency:F('raSame',false)?{name:F('raGN'),rel:F('raGR'),mobile:'+91 '+F('raGM')}:{name:F('raEN'),rel:'Emergency',mobile:'+91 '+F('raEM')},bedId:b.id,propId:b.propId,rent,deposit:dep,join:fdate(F('raJoin','2026-12-05')),months:0,kyc:'Pending',kycDoc:F('raDoc','Aadhaar · DigiLocker').replace(' · ',' (')+')',police:'Pending',status:'Active',mess:F('raMeal','No meal plan')!=='No meal plan',depStatus:F('raDepM','UPI')==='Collect later'?'Pending':'Held',addr:F('raAddr')});
 b.status='Occupied';DB.inv.push({id:'INV-'+(1300+DB.inv.length),resId:id,propId:b.propId,month:'Dec 2026',due:fdate(F('raJoin','2026-12-05')),items:[{n:'Rent · 5–31 Dec (prorated)',a:Math.round(rent*27/31)},{n:'Security deposit',a:dep}],total:Math.round(rent*27/31)+dep,paid:0,status:'Due',issued:TODAY});
 clearF('ra');delete ST.ui[k];rep('resAdded',{id})};
def('resAdded',{t:'Resident added (success)',m:M4,r:'owner',tab:'resList',code:'R-04',hide:true,d:'Success state after adding a resident. Shows the invite that goes out on WhatsApp and the next actions.',
 v:p=>{const r=RS(p.id);return page({bar:'',noMode:true,body:`<div class="empty" style="padding-top:50px"><div class="big" style="background:var(--green-50);color:var(--green);border-radius:50%">${ic('check','xl')}</div><div class="t-xl w7">${r.name} added</div><div class="mut">${loc(r)} is now occupied. First invoice ${inr(resInv(r.id).total)} created.</div></div>
 ${card(`<div class="row t-s w7" style="color:#1DA851">${ic('whats','sm')}Invite on WhatsApp</div><div class="t-s" style="margin-top:6px">Hi ${r.first}, you’ve been added to <b>${PR(r.propId).name}</b>, ${bedName(BD(r.bedId))}. Activate your resident account: pgerp.in/i/${r.id.toUpperCase()}</div>`,'',{style:'background:#E7F7EC;border-color:#CBEBD5'})}
 ${btn('Collect deposit & rent now',{icon:'rupee',go:'payRecord',p:{inv:resInv(r.id).id}})}${btn('View resident profile',{k:'s',act:'resAddedView',p:{id:r.id}})}${btn('Add another resident',{k:'g',act:'resAddedNew'})}`})}});
A.resAddedView=p=>rep('resProfile',{id:p.id});A.resAddedNew=()=>rep('resAdd',{});

def('kycVerify',{t:'KYC verification',m:M4,r:'owner',tab:'resList',code:'R-05',dp:{id:'r2'},pre:()=>{const k=DB.res.find(r=>r.kyc!=='Verified');if(k)S.kycVerify.dp={id:k.id}},d:'Owner/manager reviews documents a resident uploaded. Shows a masked ID, details matched against the resident record, and a checklist. Approve or reject with a reason the resident sees.',try:['Tap Approve.','Or tap Reject to choose a reason.'],
 v:p=>{const r=RS(p.id);return page({title:'Review KYC',sub:r.name,body:`${sb(r.kyc)}
 <div class="g2">${['ID front (masked)','ID back'].map(x=>`<div><div class="ph" style="aspect-ratio:1.55">${ic('badge','xl')}</div><div class="t-xs mut" style="text-align:center;margin-top:4px">${x}</div></div>`).join('')}</div>
 ${card(kv([['Document',r.kycDoc],['Number','XXXX XXXX 4821'],['Name on ID',r.name+' '+ic('check','sm c-ok')],['Date of birth',r.dob+' '+ic('check','sm c-ok')],['Address','Matches permanent address '+ic('check','sm c-ok')],['Uploaded','2 Dec 2026 · 8:12 AM, by resident']]))}
 ${sec('Checklist')}${list([['kc1','Photo matches the resident'],['kc2','Document is clear and not expired'],['kc3','Only last 4 Aadhaar digits visible']].map(([id,t])=>li({lead:cbx(id,false),title:t,chev:false})))}`,
 foot:btn('Reject',{k:'s',act:'sheet',p:{s:'kycRej',id:r.id}})+btn('Approve',{k:'ok',icon:'check',act:'kycOk',p:{id:r.id}})})}});
A.kycOk=p=>{if(!['kc1','kc2','kc3'].every(k=>F(k,false))){toast('Tick all 3 checks before approving','err');return}RS(p.id).kyc='Verified';back();toast('KYC approved · resident notified')};
SH.kycRej=p=>`<b class="t-l">Reject KYC</b>${pick('kr',['Photo is blurry','Document expired','Name doesn’t match','Full Aadhaar visible','Wrong document'],{l:'Reason (resident will see this)',req:true})}${ta('krn',{l:'Note (optional)',ph:'e.g. Please upload a masked Aadhaar'})}${btn('Reject and ask to re-upload',{k:'d',act:'kycNo',p:{id:p.id}})}`;
A.kycNo=p=>{if(!validate(['kr']))return;RS(p.id).kyc='Rejected';closeOv();back();toast('KYC rejected · resident asked to re-upload')};

// ---------- CHECK-OUT ----------
const coSteps=['Details','Dues','Deposit','Confirm'];
def('checkout',{t:'Check-out & settlement',m:M4,r:'owner',tab:'resList',code:'R-06',dp:{id:'r1'},pre:()=>{const k=DB.res.find(r=>r.name==='Kunal Mehta');if(k)S.checkout.dp={id:k.id}},d:'Guided check-out: date and room inspection → final dues (prorated rent, final electricity reading, damages) → deposit settlement with deductions → refund. On confirm, the bed becomes available and the refund is recorded.',try:['Step through all four steps.','Switch “Room damage found” on and change the amount — the refund recalculates.','Confirm to see the bed freed and refund recorded.'],data:'Example from the spec: deposit ₹10,000 − damage ₹1,000 − other ₹500 = ₹8,500 when no rent is pending.',
 v:p=>{const r=RS(p.id),s=+U(K('co'),0),i=resInv(r.id),R=RM(BD(r.bedId).roomId);
 const days=5,pr=F('coPr',true)?Math.round(r.rent*days/31):0,bal=i.status==='Paid'?0:(F('coPr',true)?pr:i.total-i.paid);
 const fin=+F('coMeter',R.meterCur+38),el=Math.max(0,Math.round((fin-R.meterCur)*9/Math.max(1,DB.beds.filter(b=>b.roomId===R.id&&b.status==='Occupied').length)));
 const dmg=F('coDmgOn',true)?+String(F('coDmg','1000')).replace(/\D/g,''):0,oth=+String(F('coOth','500')).replace(/\D/g,'')||0;
 const ded=bal+el+dmg+oth,ref=r.deposit-ded;let body='';
 if(s===0) body=`${card(`<div class="row"><div class="av">${initials(r.name)}</div><div><div class="w7">${r.name}</div><div class="t-s mut">${loc(r)} · since ${r.join}</div></div></div>`)}
  ${inp('coDate',{l:'Check-out date',type:'date',v:'2026-12-05',req:true})}${pick('coWhy',['Course completed','Job change','Moving to own flat','Not satisfied','Other'],{l:'Reason',v:'Job change'})}
  ${sec('Room inspection')}${list([['coK','Room keys returned',true],['coC','Cupboard & room cleared',true],['coI','ID / access card returned',false]].map(([id,t,d])=>li({lead:cbx(id,d),title:t,chev:false})))}
  ${list([togRow('coDmgOn','Room damage found','Add details and charge in step 3',true)])}${F('coDmgOn',true)?ta('coDmgN',{l:'Damage details',v:'Study chair broken, wall marks near bed'})+upl('coDmgPh','Add damage photos','damage_1.jpg'):''}
  ${inp('coMeter',{l:`Final meter reading (last: ${R.meterCur})`,v:String(R.meterCur+38),im:'numeric',h:'Used to charge electricity till the check-out date'})}`;
 if(s===1) body=`${card(`${lbl('Pending dues')}${kv([[`${i.month} invoice`,i.status==='Paid'?'Paid':inr(i.total-i.paid)],[F('coPr',true)?`Rent 1–5 Dec (prorated, ${days} days)`:'Full December rent',inr(bal)],[`Electricity (${fin-R.meterCur} units × ₹9 ÷ beds)`,inr(el)]])}`)}
  ${list([togRow('coPr','Prorate December rent','Charge only till the check-out date',true)])}
  ${inp('coOth',{l:'Other charges',pre:'₹',v:'500',im:'numeric',h:'e.g. deep cleaning, lost key'})}
  ${card(`<div class="between"><b>Total dues</b><b class="t-l num">${inr(bal+el+oth)}</b></div><div class="t-s mut">Will be deducted from the deposit</div>`)}`;
 if(s===2) body=`${card(`${lbl('Deposit settlement')}<div style="margin-top:8px">${kv([['Deposit collected ('+r.join+')',inr(r.deposit)],['Pending rent',bal?'− '+inr(bal):'₹0'],['Electricity',el?'− '+inr(el):'₹0'],['Damage',dmg?'− '+inr(dmg):'₹0'],['Other charges',oth?'− '+inr(oth):'₹0']])}</div><div class="between" style="border-top:1px dashed var(--stroke);margin-top:10px;padding-top:10px"><b>${ref>=0?'Refund to resident':'Resident owes'}</b><b class="t-xl num ${ref>=0?'c-ok':'c-err'}">${inr(Math.abs(ref))}</b></div>`)}
  ${F('coDmgOn',true)?inp('coDmg',{l:'Damage charge',pre:'₹',v:'1000',im:'numeric'}):''}
  ${ref>=0?pick('coRM',['UPI','Bank transfer','Cash'],{l:'Refund method',v:'UPI'})+(F('coRM','UPI')==='UPI'?inp('coUpi',{l:'Resident UPI ID',v:r.first.toLowerCase()+'@okhdfcbank',req:true,pat:'[a-zA-Z0-9.\\-_]{2,}@[a-zA-Z]{2,}',msg:'Enter a valid UPI ID like name@bank'}):''):banner('err','alert','Deductions are more than the deposit. Collect the balance before closing.')}`;
 if(s===3) body=`${banner('warn','alert','This can’t be undone. The bed will be marked available and the resident’s app access will switch to view-only.')}${card(kv([['Resident',r.name],['Bed released',bedName(BD(r.bedId))],['Check-out date',fdate(F('coDate','2026-12-05'))],['Total deductions',inr(ded)],[ref>=0?'Refund':'To collect',inr(Math.abs(ref))],['Refund via',ref>=0?F('coRM','UPI')+(F('coRM','UPI')==='UPI'?' · '+F('coUpi',r.first.toLowerCase()+'@okhdfcbank'):''):'—']]))}${list([togRow('coSend','Send settlement statement on WhatsApp','',true)])}`;
 return page({title:'Check-out',sub:`${r.name} · ${coSteps[s]}`,body:`${stepper(coSteps,s)}${body}`,foot:(s>0?btn('Back',{k:'s',act:'ui',p:{k:K('co'),v:s-1}}):'')+(s<3?btn('Next',{act:'coNext',p:{s}}):btn('Complete check-out',{k:'d',act:'coAsk',p:{id:r.id,ref}}))})}});
A.coNext=p=>{const s=+p.s;if(s===0&&!F('coK',true)){toast('Collect the room keys first','err');return}if(s===2&&F('coRM','UPI')==='UPI'&&!validate(['coUpi']))return;ST.ui[K('co')]=s+1;render(true)};
A.coAsk=p=>confirmD({icon:'out',danger:true,title:'Complete check-out?',msg:`${RS(p.id).name} will be checked out and ${inr(Math.max(0,+p.ref))} refunded. The bed becomes available for new residents.`,ok:'Complete',act:'coDo',p});
A.coDo=p=>{const r=RS(p.id);r.status='Checked out';r.depStatus=+p.ref>0?'Refunded':'Settled';const b=BD(r.bedId);b.status='Available';const i=resInv(r.id);i.paid=i.total;i.status='Paid';delete ST.ui[K('co')];clearF('co');rep('coDone',{id:r.id,ref:p.ref})};
def('coDone',{t:'Check-out complete',m:M4,r:'owner',tab:'resList',code:'R-07',hide:true,d:'Success state of check-out.',
 v:p=>{const r=RS(p.id);return page({bar:'',noMode:true,body:`<div class="empty" style="padding-top:60px"><div class="big" style="background:var(--green-50);color:var(--green);border-radius:50%">${ic('check','xl')}</div><div class="t-xl w7">${r.first} checked out</div><div class="mut">Refund of <b>${inr(Math.max(0,+p.ref))}</b> recorded. ${bedName(BD(r.bedId))} is now <b class="c-ok">available</b>.</div></div>${btn('View bed',{k:'s',act:'coBed',p:{b:r.bedId}})}${btn('Share settlement statement',{k:'wa',icon:'whats',act:'toast',p:{m:'Settlement statement sent on WhatsApp'}})}${btn('Back to residents',{k:'g',tab:'resList'})}`})}});
A.coBed=p=>rep('bedDetail',{id:p.b});

// ---------- RESERVATIONS ----------
def('resvList',{t:'Reservations',m:M5,r:'owner',tab:'resList',code:'B-01',d:'Upcoming bookings with advance status, the waitlist (people waiting for a bed type) and history (checked-in or cancelled).',try:['Open the Waitlist tab and tap “Offer bed”.','Tap “New reservation”.'],
 empty:{icon:'cal',title:'No reservations yet',msg:'Reserve a bed for someone joining later and collect an advance.',cta:'New reservation',go:'resvCreate'},
 v:()=>{const t=U('rvt','up'),rv=DB.resv.filter(r=>inS(r.propId)),up=rv.filter(r=>['Confirmed','Pending payment'].includes(r.status)),hi=rv.filter(r=>!['Confirmed','Pending payment'].includes(r.status)),w=DB.wait.filter(x=>inS(x.propId));
 return page({chip:true,fab:['New reservation',{go:'resvCreate'}],body:`<div class="g3">${[['Upcoming',up.length],['Advance held',inr(sum(up.filter(r=>r.adv==='Paid'),r=>r.advance))],['Waitlist',w.length]].map(([l,v])=>card(`<div class="w7 t-m num">${v}</div><div class="t-xs mut">${l}</div>`,'',{style:'padding:10px;text-align:center'})).join('')}</div>
 ${tabsBar('rvt',[['up','Upcoming'],['wait','Waitlist'],['hist','History']],'up')}
 ${t==='up'?(up.length?list(up.map(r=>li({icon:'cal',bg:'var(--violet-50)',fg:'var(--violet)',title:r.name,sub:`${PR(r.propId).short} · ${bedName(BD(r.bedId))}`,sub2:`Check-in ${r.from} · advance ${inr(r.advance)}`,right:sb(r.status),go:'resvDetail',p:{id:r.id}}))):emptyB({icon:'cal',title:'No upcoming reservations',msg:'Tap New reservation to book a bed.'})):''}
 ${t==='wait'?list(w.map(x=>li({icon:'clock',title:x.name,sub:`${PR(x.propId).short} · ${x.pref}`,sub2:`Budget ${inr(x.budget)} · waiting since ${x.since}`,right:btn('Offer bed',{k:'s',sm:true,act:'toast',p:{m:'Available beds sent to '+x.name.split(' ')[0]+' on WhatsApp'}}),chev:false})))+btn('Add to waitlist',{k:'s',icon:'plus',act:'toast',p:{m:'Waitlist form: name, mobile, property, preference, budget'}}):''}
 ${t==='hist'?list(hi.map(r=>li({icon:'cal',title:r.name,sub:`${PR(r.propId).short} · ${r.from}`,right:sb(r.status),go:'resvDetail',p:{id:r.id}}))):''}<div style="height:50px"></div>`})}});

def('resvCreate',{t:'Create reservation',m:M5,r:'owner',tab:'resList',code:'B-02',d:'Pick property and dates first; the bed picker then shows which beds are free for those dates. Beds already reserved or occupied for overlapping dates can’t be picked and explain why. Then enter the person and collect an advance.',try:['Tap a blue (reserved) bed — you’ll see “This bed is already reserved for the selected dates.”','Pick a green bed, fill name and mobile, then Confirm.'],data:'Overlap rule: a bed is blocked if any confirmed reservation or stay overlaps the chosen check-in → check-out range. Occupied beds whose resident leaves before the check-in date become bookable.',
 v:p=>{if(p.bed&&!F('rcBed'))setF({rcBed:p.bed,rcProp:BD(p.bed).propId});const pid=F('rcProp',ST.prop==='all'?'p1':ST.prop),from=F('rcFrom','2026-12-10'),sel_=F('rcBed'),fromN=dnum(from);
 const avail=b=>{if(b.status==='Available')return true;if(b.status==='Occupied'){const r=resOnBed(b.id);return r&&r.status==='Notice'&&r.checkout&&new Date(r.checkout)<new Date(from)}return false};
 return page({title:'New reservation',close:true,body:`${sel('rcProp',DB.props.map(P=>[P.id,P.name]),{l:'Property',v:pid,live:true})}
 <div class="g2">${inp('rcFrom',{l:'Check-in',type:'date',v:'2026-12-10',live:true,req:true})}${inp('rcTo',{l:'Expected check-out',type:'date',v:'2027-05-31'})}</div>
 <div class="between">${lbl('Available beds for these dates')}<span class="t-xs mut">${DB.beds.filter(b=>b.propId===pid&&avail(b)).length} free</span></div>
 ${ST.err.rcBed?`<div class="help err">${ic('alert','sm')}${ST.err.rcBed}</div>`:''}
 <div id="rcBed">${DB.blds.filter(B=>B.propId===pid).map(B=>`<div class="t-s w7" style="margin:6px 0">${B.name}</div><div class="bedgrid" style="grid-template-columns:repeat(auto-fill,minmax(58px,1fr))">${DB.beds.filter(b=>b.bldId===B.id).map(b=>{const ok=avail(b);return `<div class="bed ${ok?'Available':b.status} ${b.id===sel_?'sel':''} ${ok?'':'blk'}" data-act="rcBed" data-p="id:${b.id},ok:${ok?1:0}" role="button" tabindex="0" style="min-height:52px;padding:5px 2px"><span>${RM(b.roomId).no}</span><span class="t-xs">Bed ${b.label}</span></div>`}).join('')}</div>`).join('')}</div>
 ${sel_?card(`<div class="between"><b>${bedName(BD(sel_))}</b>${bdg('Selected','info')}</div><div class="t-s mut">${RM(BD(sel_).roomId).type} · ${inr(RM(BD(sel_).roomId).rent)}/month</div>`):''}
 ${lbl('Person')}${inp('rcName',{l:'Name',v:p.name||'',ph:'Prospect name',req:true,msg:'Enter the name'})}${inp('rcMob',{l:'Mobile',pre:'+91',im:'numeric',max:10,req:true,pat:'[6-9][0-9]{9}',msg:'Enter a valid 10-digit mobile number'})}
 <div class="g2">${inp('rcAdv',{l:'Advance',pre:'₹',v:'2000',im:'numeric',req:true,pat:'[0-9]{3,6}',msg:'Enter advance amount'})}${sel('rcMode',['UPI','Cash','Payment link'],{l:'Collected by',v:'UPI'})}</div>
 ${ta('rcNote',{l:'Notes',ph:'e.g. joining after exams, prefers lower bunk'})}`,foot:btn('Confirm reservation',{act:'rcSave'})})}});
A.rcBed=p=>{if(p.ok!=='1'){toast('This bed is already reserved for the selected dates.','err');return}ST.f.rcBed=p.id;delete ST.err.rcBed;render()};
A.rcSave=p=>{if(!F('rcBed')){ST.err.rcBed='Select an available bed';render();toast('Please select a bed','err');return}if(!validate(['rcFrom','rcName','rcMob','rcAdv']))return;
 const b=BD(F('rcBed')),id='RSV-'+(400+DB.resv.length);DB.resv.unshift({id,name:F('rcName'),mobile:'+91 '+F('rcMob'),bedId:b.id,propId:b.propId,from:fdate(F('rcFrom','2026-12-10')),to:fdate(F('rcTo','2027-05-31')),advance:+F('rcAdv','2000'),adv:F('rcMode','UPI')==='Payment link'?'Pending':'Paid',status:F('rcMode','UPI')==='Payment link'?'Pending payment':'Confirmed',note:F('rcNote',''),created:TODAY});
 if(b.status==='Available')b.status='Reserved';clearF('rc');rep('resvDone',{id})};
def('resvDone',{t:'Reservation confirmed',m:M5,r:'owner',tab:'resList',code:'B-03',hide:true,d:'Success state with a shareable confirmation.',
 v:p=>{const r=DB.resv.find(x=>x.id===p.id);return page({bar:'',noMode:true,body:`<div class="empty" style="padding-top:50px"><div class="big" style="background:var(--green-50);color:var(--green);border-radius:50%">${ic('check','xl')}</div><div class="t-xl w7">Bed reserved</div><div class="mut">${r.name} · ${PR(r.propId).short} ${bedName(BD(r.bedId))}</div></div>${card(kv([['Reservation no.',r.id],['Check-in',r.from],['Expected check-out',r.to],['Advance',inr(r.advance)+' · '+r.adv]]))}${btn('Send confirmation on WhatsApp',{k:'wa',icon:'whats',act:'toast',p:{m:'Confirmation sent to '+r.name.split(' ')[0]}})}${btn('View reservation',{k:'s',act:'rvView',p:{id:r.id}})}${btn('Done',{k:'g',act:'rvDoneBack'})}`})}});
A.rvView=p=>rep('resvDetail',{id:p.id});A.rvDoneBack=()=>back();

def('resvDetail',{t:'Reservation details',m:M5,r:'owner',tab:'resList',code:'B-04',dp:{id:'RSV-301'},d:'One reservation: person, bed, dates, advance and its timeline. Convert it to a check-in (opens Add resident pre-filled), collect the balance, or cancel (bed becomes free; advance refund recorded).',try:['Tap “Cancel reservation” to see the confirmation dialog.','Tap “Convert to check-in”.'],
 v:p=>{const r=DB.resv.find(x=>x.id===p.id)||DB.resv[0],b=BD(r.bedId),act=['Confirmed','Pending payment'].includes(r.status);
 return page({title:r.name,sub:r.id,body:`<div class="chips">${sb(r.status)}${bdg('Advance '+r.adv.toLowerCase(),r.adv==='Paid'?'ok':r.adv==='Pending'?'warn':'mute')}</div>
 ${card(kv([['Mobile',r.mobile],['Property',PR(r.propId).name],['Bed',bedName(b)+' · '+RM(b.roomId).type],['Check-in',r.from],['Expected check-out',r.to],['Monthly rent',inr(RM(b.roomId).rent)],['Advance',inr(r.advance)],['Notes',r.note||'—']]))}
 ${sec('Timeline')}${card(tl([['Reservation created',r.created+' · by Deven Patel','ok'],['Advance '+(r.adv==='Paid'?'received':'requested'),inr(r.advance)+' · UPI',r.adv==='Paid'?'ok':'on'],['Check-in',r.from,r.status==='Checked in'?'ok':'']]))}
 ${act?btn('Convert to check-in',{icon:'in',go:'resAdd',p:{bed:r.bedId,name:r.name,mob:r.mobile.replace('+91 ','').replace(' ','')}})+(r.adv!=='Paid'?btn('Send payment link',{k:'s',icon:'share',act:'toast',p:{m:'Razorpay payment link sent on WhatsApp'}}):'')+btn('Cancel reservation',{k:'g',act:'rvCancel',p:{id:r.id},style:'color:var(--red)'}):''}`})}});
A.rvCancel=p=>confirmD({icon:'alert',danger:true,title:'Cancel this reservation?',msg:'The bed becomes available again. The advance will be marked for refund.',ok:'Cancel booking',cancel:'Keep',act:'rvCancelDo',p});
A.rvCancelDo=p=>{const r=DB.resv.find(x=>x.id===p.id);r.status='Cancelled';r.adv='Refund due';const b=BD(r.bedId);if(b.status==='Reserved')b.status='Available';closeOv();render();toast('Reservation cancelled · bed is available')};
